CREATE TRIGGER RefCusRate_Combined
	ON RefCusRate
	FOR INSERT, UPDATE, DELETE
	AS
	IF (SELECT CASE WHEN EXISTS(SELECT 1 FROM INSERTED) AND NOT EXISTS(SELECT 1 FROM DELETED) THEN 1 ELSE 0 end) = 1
	BEGIN
		UPDATE t SET
		ZZ2_DataSetPK = COALESCE(inserted.ZZ2_ZZ1_Tariff, ZZW_ZZ1_Tariff),
		ZZ2_DataSetCode = CASE WHEN inserted.ZZ2_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' ELSE CASE WHEN ZZW_ZZ1_Tariff IS NOT NULL THEN 'ZZ1' END END 
		FROM RefCusRate t
		JOIN inserted ON t.ZZ2_PK = inserted.ZZ2_PK
		LEFT JOIN RefCusTariffNationalCode ON inserted.ZZ2_ZZW_TariffNationalCode = ZZW_PK
	END

	DECLARE @sourcePK SourcePKList;
	INSERT @sourcePK
	SELECT t.ZZ2_DataSetPK, t.ZZ2_DataSetCode
	FROM RefCusRate t
	JOIN inserted ON t.ZZ2_PK = inserted.ZZ2_PK
	UNION
	SELECT ZZ2_DataSetPK, ZZ2_DataSetCode
	FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN @sourcePK ON RVC_ParentPK = PK AND RVC_ParentCode = TablePrefix
	WHERE RVC_IsPublished = 1

	EXEC dbo.RecordDataSetChangeHistory @sourcePK
GO

CREATE TRIGGER RefCusRate_DataProcessingResult_Delete
	ON RefCusRate
	FOR DELETE
	AS
	BEGIN
		DELETE dpr
		FROM dbo.RefStagingDatabase_DataProcessingResult dpr
		JOIN deleted d ON dpr.DPR_ParentPK = d.ZZ2_PK
	END
GO
